style.css:
/* ===== CANVA — TEMA FUCSIA + NEGRO ===== */

/* Fondo general */
body,
html {
    background: #ff1493 !important;
}

/* Área principal del editor */
[class*="workspace"],
[class*="editor"],
[class*="design"] {
    background-color: #ff1493 !important;
}

/* Barra lateral y paneles */
nav,
aside,
[class*="sidebar"],
[class*="panel"] {
    background-color: #000000 !important;
}

/* Botones */
button {
    background-color: #000000 !important;
    color: #ff1493 !important;
    border-color: #ff1493 !important;
}

/* Botones al pasar el mouse */
button:hover {
    background-color: #ff1493 !important;
    color: #000000 !important;
}

/* Textos de la interfaz */
[class*="sidebar"] *,
nav *,
button * {
    color: #ffffff !important;
}

/* Campos de búsqueda e inputs */
input,
textarea {
    background-color: #000000 !important;
    color: #ffffff !important;
    border-color: #ff1493 !important;
}

/* Menús desplegables */
[role="menu"],
[role="dialog"],
[role="listbox"] {
    background-color: #000000 !important;
    color: #ffffff !important;
}

/* Iconos */
svg {
    color: #ff1493 !important;
}

/* Barras superiores */
header {
    background-color: #000000 !important;
}
